func:
// Remember which source IP each moteId last sent from, so commands
// (e.g. SET_PERIOD) can be routed back to the correct physical/simulated node
// instead of a single hardcoded address.
if (msg.ip && msg.payload && typeof msg.payload.moteId !== 'undefined') {
    flow.set('node_ip_' + msg.payload.moteId, msg.ip);
}
return msg;

msg.url = "http://localhost:8080/traffic"; 
msg.payload = { 
    moteId: msg.payload.moteId 
};
return msg;

msg.url = "http://localhost:8080/parent";
var raw = msg.payload.newParentId || "";
// Cooja IPv6: first group first byte = mote ID (e.g. "0201:..." → 2)
var parts = raw.split(":");
var parentInt = parts.length > 0 ? parseInt(parts[0].substring(0,2), 16) : 0;
msg.payload = {
    moteId: msg.payload.moteId,
    newParentId: parentInt
};
return msg;

msg.url = "http://localhost:8080/crash";
msg.payload = { 
    moteId: msg.payload.moteId 
};
return msg;

// ModeActor -> Node-RED: UDP to Contiki + HTTP response to Akka
const body = msg.payload || {};
const moteId = body.moteId;
const newT = (typeof body.newT !== 'undefined') ? body.newT
    : (typeof body.periodT !== 'undefined') ? body.periodT
        : (typeof body.newTStr !== 'undefined') ? parseInt(body.newTStr, 10)
            : undefined;

if (typeof newT === 'undefined' || Number.isNaN(Number(newT))) {
    node.warn("Missing or invalid newT/periodT in payload: " + JSON.stringify(body));
    const errMsg = RED.util.cloneMessage(msg);
    errMsg.payload = { error: "missing newT/periodT" };
    errMsg.statusCode = 400;
    return [null, errMsg];
}

// Output 1: UDP — JSON string (Contiki does json.loads on the packet)
// Routed to the mote's last-seen source IP (set by the IP Tracker node), so the
// command reaches the specific mote instead of a single fixed address.
const trackedIp = flow.get('node_ip_' + moteId);
if (!trackedIp) {
    node.warn("No tracked IP for mote " + moteId + " yet — falling back to localhost");
}
const udpMsg = RED.util.cloneMessage(msg);
udpMsg.ip = trackedIp || 'localhost';
udpMsg.payload = JSON.stringify({
    action: "SET_PERIOD",
    value: Number(newT),
    moteId: moteId
});

// Output 2: HTTP response — clone keeps req/res (fixes "No response object")
const resp = RED.util.cloneMessage(msg);
resp.payload = { status: "ok" };
resp.statusCode = 200;

return [udpMsg, resp];

// MoteManager -> Node-RED: symmetric recovery. Mirrors the actor twin's own
// restart-on-crash by telling the physical/simulated mote to resume operation.
const body = msg.payload || {};
const moteId = body.moteId;

if (typeof moteId === 'undefined') {
    node.warn("Missing moteId in revive request: " + JSON.stringify(body));
    const errMsg = RED.util.cloneMessage(msg);
    errMsg.payload = { error: "missing moteId" };
    errMsg.statusCode = 400;
    return [null, errMsg];
}

const trackedIp = flow.get('node_ip_' + moteId);
if (!trackedIp) {
    node.warn("No tracked IP for mote " + moteId + " yet — falling back to localhost");
}
const udpMsg = RED.util.cloneMessage(msg);
udpMsg.ip = trackedIp || 'localhost';
udpMsg.payload = JSON.stringify({
    action: "REVIVE",
    moteId: moteId
});

const resp = RED.util.cloneMessage(msg);
resp.payload = { status: "ok" };
resp.statusCode = 200;

return [udpMsg, resp];
